PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS statement_imports(id INTEGER PRIMARY KEY,filename TEXT NOT NULL,imported_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS receipts(id INTEGER PRIMARY KEY,filename TEXT NOT NULL,image_path TEXT NOT NULL,merchant TEXT,receipt_date TEXT,amount_minor INTEGER,card_last4 TEXT CHECK(card_last4 IS NULL OR (length(card_last4)=4 AND card_last4 NOT GLOB '*[^0-9]*')),receipt_number TEXT,ocr_text TEXT,ocr_status TEXT NOT NULL CHECK(ocr_status IN ('extracted','failed','reviewed')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK(amount_minor IS NULL OR amount_minor>=0));
CREATE TABLE IF NOT EXISTS statement_lines(id INTEGER PRIMARY KEY,import_id INTEGER NOT NULL REFERENCES statement_imports(id) ON DELETE CASCADE,date TEXT NOT NULL,description TEXT NOT NULL,amount_minor INTEGER NOT NULL CHECK(amount_minor>=0),card_last4 TEXT NOT NULL CHECK(length(card_last4)=4 AND card_last4 NOT GLOB '*[^0-9]*'),ref TEXT NOT NULL,UNIQUE(import_id,ref));
CREATE INDEX IF NOT EXISTS idx_statement_match ON statement_lines(date,amount_minor,card_last4);
CREATE TABLE IF NOT EXISTS reconciliation_runs(id INTEGER PRIMARY KEY,import_id INTEGER NOT NULL REFERENCES statement_imports(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reconciliation_matches(id INTEGER PRIMARY KEY,run_id INTEGER NOT NULL REFERENCES reconciliation_runs(id) ON DELETE CASCADE,receipt_id INTEGER REFERENCES receipts(id),statement_line_id INTEGER REFERENCES statement_lines(id),status TEXT NOT NULL CHECK(status IN ('matched','duplicate','missing','mismatch')),reason TEXT NOT NULL,confidence REAL NOT NULL CHECK(confidence>=0 AND confidence<=1),CHECK(receipt_id IS NOT NULL OR statement_line_id IS NOT NULL));
CREATE UNIQUE INDEX IF NOT EXISTS one_receipt_per_run ON reconciliation_matches(run_id,receipt_id) WHERE receipt_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS one_statement_per_run ON reconciliation_matches(run_id,statement_line_id) WHERE statement_line_id IS NOT NULL AND status!='duplicate';
